app.controller("TransfersController",["postTransfer","edittransfer","deletetransfer","getBranch","getsociety","getvehiclemake","getvehiclereg","gettransfer","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder","vehicle", function(postTransfer,edittransfer,deletetransfer,getBranch,getsociety,getvehiclemake,getvehiclereg,gettransfer,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder,vehicle)  {
  $scope.branch = [];
  $scope.societyname = [];
  $scope.vehiclemake = [];
  $scope.vehiclereg = [];
  $scope.Transfer = [];

            $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    $scope.search=function(val){
       vehicle.vehiclesearch(val).then(function(data){
         $scope.vehiclereg=data;
         // console.log($scope.Vehicle)
       })
    }
    $scope.click=function(reg){
        // console.log(reg)
      $scope.transfer.regno=reg
      $scope.vehiclereg=[] 
    }
    $scope.saveTransferData = function (transfer) {
        //console.log(transfer)
        $scope.Transfer.push(transfer);
        $scope.transfer = {};
        //console.log($scope.Transfer);
        postTransfer.postingTransfer(transfer)
    }
    $scope.editsaveTransfer = function(value){
      //console.log(value)
      edittransfer.editingtransfer(value)
    }
    $scope.removeTransferItem = function(index,name){
      //console.log(name)
      deletetransfer.deletingtransfer(name)
      $scope.Transfer.splice(index, 1);
    }
    $scope.printTransfer = function(transfers) {
      //console.log(transfers.society)
      var pdf = new jsPDF('l', 'pt', 'a4');
      pdf.setFontSize(10);
      pdf.text(150,73,transfers.society);
      console.log(transfers.society);
      pdf.text(150,91,transfers.branch);
      console.log(transfers.branch);
      pdf.text(150,108,transfers.cmr);
      console.log(transfers.cmr);
      pdf.text(150,125,transfers.make);
      console.log(transfers.make);
      pdf.text(150,142,transfers.model);
      console.log(transfers.model);
      pdf.text(150,158,transfers.regno);
      console.log(transfers.regno);
      pdf.text(150,194,transfers.transferbranch);
      console.log(transfers.transferbranch);
      pdf.text(150,211,transfers.transferdate);
      console.log(transfers.transferdate);
      pdf.autoPrint();
      pdf.save('sample.pdf');
    }

    $scope.getdata=function(){
      getsociety.gettingsociety().then(function(data){
        if(data){
          $scope.societyname = data
          //console.log($scope.societyname)
        }
        else{
          $scope.societyname = []
        }
      })
      getBranch.gettingbranch().then(function(data){
        if(data){
          //console.log(data)
          $scope.branch = data
          //console.log($scope.branch)
        }
        else{
          $scope.branch = []
        }
      })
      getvehiclemake.gettingvehiclemake().then(function(data){
        if(data){
          //console.log(data)
          $scope.vehiclemake = data
          //console.log($scope.vehiclemake)
        }
        else{
          $scope.vehiclemake = []
        }
      })
    }

    $scope.getTransfersdata = function(){
      gettransfer.gettingtransfer().then(function(data){
        if(data){
          //console.log(data)
          $scope.Transfer = data
          //console.log($scope.Transfer)
        }
        else{
          $scope.Transfer = []
        }
      })
    }
}]);

