app.service('fileUpload', ['$http', function ($http) {
   this.uploadFileToUrl = function(office, uploadUrl){
      console.log(office)
      var fd = new FormData();
      for(var key in office){
        console.log(office[key])
        fd.append(key, office[key])
      }
      console.log(fd)
      data=$http.post(uploadUrl, fd, {
         transformRequest: angular.identity,
         headers: {'Content-Type': undefined}
      })
      .then(function(success){
        console.log(success.data)
        return success.data
      })
      return data
   }
}]);

