app.controller("BranchvehicleController",["postBranchvehicle","editBranchvehicle","deleteBranchvehicle","getbranchvehicle","getsociety","getbranch","getOffice",'getvehicle',"getmodel","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder","vehicle", function(postBranchvehicle,editBranchvehicle,deleteBranchvehicle,getbranchvehicle,getsociety,getbranch,getOffice,getvehicle,getmodel,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder,vehicle)  {
  $scope.Branchvehicle = [];
  $scope.Society = [];
  $scope.Branch = [];
  $scope.Staffname = [];
  $scope.Vehicle = [];
  $scope.Model = [];

         $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    $scope.search=function(val){
       vehicle.vehiclesearch(val).then(function(data){
         $scope.Vehicle=data;
         // console.log($scope.Vehicle)
       })
    }
    $scope.click=function(reg){
        // console.log(reg)
      $scope.branchvehicle.vehicleregno=reg
      $scope.Vehicle=[] 
    }
    $scope.savebranchvehicledata = function (branchvehicle) {
        //console.log(branchvehicle)
        $scope.Branchvehicle.push(branchvehicle);
        postBranchvehicle.postingbranchvehicle(branchvehicle)
        $scope.branchvehicle = {};
    }
    $scope.editsaveBranchvehicle = function(value){
      //console.log(value)
      editBranchvehicle.editingBranchvehicle(value)
    }
    $scope.removeBranchvehicleItem = function(index,name){
      //console.log(name)
      deleteBranchvehicle.deletingBranchvehicle(name)
      $scope.Branchvehicle.splice(index, 1);
    }

    $scope.getdata = function(){
      getsociety.gettingsociety().then(function(data){
        if(data){
          //console.log(data)
          $scope.Society = data
          //console.log($scope.Society)
        }
        else{
          $scope.Society = []
        }
      })
      getbranch.gettingbranch().then(function(data){
        if(data){
          //console.log(data)
          $scope.Branch = data
          //console.log($scope.Branch)
        }
        else{
          $scope.Branch = []
        }
      })
      getOffice.gettingOffice().then(function(data){
        if(data){
          //console.log(data)
          $scope.Staffname = data
          //console.log($scope.Staffname)
        }
        else{
          $scope.Staffname = []
        }
      })
      getmodel.gettingModel().then(function(data){
        if(data){
          // console.log(data)
          $scope.Model = data
          //console.log($scope.Model)
        }
        else{
          $scope.Model = []
        }
      })
    }

    $scope.getbranchvehicledata = function(){
      getbranchvehicle.gettingBranchvehicle().then(function(data){
        if(data){
          console.log(data)
          $scope.Branchvehicle = data
          //console.log($scope.Branchvehicle)
        }
        else{
          $scope.Branchvehicle = []
        }
      })
    }
}]);

