app.service('fileUpload', ['$http', function ($http) {
   this.uploadFileToUrl = function(vehicleaccident, uploadUrl){
      console.log(vehicleaccident)
      var fd = new FormData();
      for(var key in vehicleaccident){
        console.log(vehicleaccident[key])
        fd.append(key, vehicleaccident[key])
      }
      console.log(fd)
      data=$http.post(uploadUrl, fd, {
         transformRequest: angular.identity,
         headers: {'Content-Type': undefined}
      })
      .then(function(success){
        console.log(success.data)
        return success.data
      })
      return data
   }
}]);

