app.controller("RoadtaxController",["vehicle","postRoadtax","editRoadtax","deleteRoadtax","fileUpload","getRoadtaxdata","getsociety","getbranch","getvehiclereg","getvehiclemake","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder", function(vehicle,postRoadtax,editRoadtax,deleteRoadtax,fileUpload,getRoadtaxdata,getsociety,getbranch,getvehiclereg,getvehiclemake,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder)  {
  $scope.Roadtax = [];
  $scope.Society = [];
  $scope.vehiclereg = [];
  $scope.Branch = [];
  $scope.vehiclemake = [];

        $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    $scope.search=function(val){
       vehicle.vehiclesearch(val).then(function(data){
         $scope.vehiclereg=data;
         // console.log($scope.Vehicle)
       })
    }
    $scope.click=function(reg){
        // console.log(reg)
      $scope.roadtaxes.regno=reg
      $scope.vehiclereg=[] 
    }
    $scope.saveRoadtax = function (roadtaxes) {
        var roadtaxes = $scope.roadtaxes
        var uploadUrl = "/roadtaxfiledata";
        fileUpload.uploadFileToUrl(roadtaxes, uploadUrl)
        $scope.Roadtax.push(roadtaxes);
        $scope.roadtaxes = {};
    }
    $scope.editsaveRoadtax = function(value){
      //console.log(value)
      // editRoadtax.editingRoadtax(value)
      var uploadUrl = "/EditRoadtax";
      fileUpload.uploadFileToUrl(value, uploadUrl)
    }
    $scope.removeRoadtaxItem = function(index,name){
      //console.log(name)
      deleteRoadtax.deletingRoadtax(name)
      $scope.Roadtax.splice(index, 1);
    }

    $scope.getdata=function(){
      getsociety.gettingsociety().then(function(data){
        if(data){
          //console.log(data)
          $scope.Society = data
          //console.log($scope.Society)
        }
        else{
          $scope.Society = []
        }
      })
      getvehiclemake.gettingvehiclemake().then(function(data){
        if(data){
          //console.log(data)
          $scope.vehiclemake = data
          //console.log($scope.vehiclemake)
        }
        else{
          $scope.vehiclemake = []
        }
      })
       getbranch.gettingbranch().then(function(data){
        if(data){
          //console.log(data)
          $scope.Branch = data
          //console.log($scope.Branch)
        }
        else{
          $scope.Branch = []
        }
      })
    }

    $scope.getRoadtax = function(){
      getRoadtaxdata.gettingRoadtax().then(function(data){
        if(data){
          //console.log(data)
          $scope.Roadtax = data
          //console.log($scope.Roadtax)
        }
        else{
          $scope.Roadtax = []
        }
      })
    }
}]);
app.service('fileUpload', ['$http', function ($http) {
   this.uploadFileToUrl = function(roadtaxes, uploadUrl){
      console.log(roadtaxes)
      var fd = new FormData();
      for(var key in roadtaxes){
        console.log(roadtaxes[key])
        fd.append(key, roadtaxes[key])
      }
      console.log(fd)
      data=$http.post(uploadUrl, fd, {
         transformRequest: angular.identity,
         headers: {'Content-Type': undefined}
      })
      .then(function(success){
        console.log(success.data)
        return success.data
      })
      return data
   }
}]);
