app.controller("DashboardGradeController",["getBusfill","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder", function(getBusfill,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder)  {
  $scope.gradeA= []
  $scope.gradeB= []
  $scope.gradeC= []
  $scope.gradeD= []

      $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    
      $scope.getdata = function(){
        getBusfill.gettingbusfill().then(function(data){
          if(data){
            let dates_A = [];
            let dates_B = [];
            let dates_C = [];
            let dates_D = [];
            for(i=0;i<data.length;i++){
              if(data[i].date!='Invalid date'){
                var grade = data[i].grade
                if(grade=="A"){
                  dates_A.push(data[i].date)
                }
                else if(grade=="B"){
                  dates_B.push(data[i].date)
                }
                else if(grade=="C"){
                  dates_C.push(data[i].date)
                }
                else if(grade=="D"){
                  dates_D.push(data[i].date)
                }
              }
              
            }
            // console.log(dates_A);
            // console.log(dates_B);
            // console.log(dates_C);
            // console.log(dates_D);

            const maxDateA = new Date(
              Math.max(
                ...dates_A.map(element => {
                  return new Date(element);
                }),
              ),
            );

            const maxDateB = new Date(
              Math.max(
                ...dates_B.map(element => {
                  return new Date(element);
                }),
              ),
            );

            const maxDateC = new Date(
              Math.max(
                ...dates_C.map(element => {
                  return new Date(element);
                }),
              ),
            );


            const maxDateD = new Date(
              Math.max(
                ...dates_D.map(element => {
                  return new Date(element);
                }),
              ),
            );

            var grade_A_date = maxDateA.getFullYear()+'-'+("0"+(maxDateA.getMonth()+1)).slice(-2)+'-'+("0"+maxDateA.getDate()).slice(-2)
            var grade_B_date = maxDateB.getFullYear()+'-'+("0"+(maxDateB.getMonth()+1)).slice(-2)+'-'+("0"+maxDateB.getDate()).slice(-2)
            var grade_C_date = maxDateC.getFullYear()+'-'+("0"+(maxDateC.getMonth()+1)).slice(-2)+'-'+("0"+maxDateC.getDate()).slice(-2)
            var grade_D_date = maxDateD.getFullYear()+'-'+("0"+(maxDateD.getMonth()+1)).slice(-2)+'-'+("0"+maxDateD.getDate()).slice(-2)
            // console.log(grade_A_date);
            // console.log(grade_B_date);
            // console.log(grade_C_date);
            // console.log(grade_D_date);

            //console.log(today);

            for(i=0;i<data.length;i++){
              var grade = data[i].grade
              var dateStr = data[i].date
            // console.log(dateStr)
            // var date = dateStr.getFullYear()+'-'+("0"+(dateStr.getMonth()+1)).slice(-2)+'-'+("0"+dateStr.getDate()).slice(-2)
              // $scope.dt = $filter('date')(new Date(dateStr.split("-").join('/')), "yyyy-MM-dd");
              // console.log($scope.dt)
            if(grade=="A" && dateStr==grade_A_date){

              $scope.gradeA.push(data[i])
            }
            else if(grade=="B" && dateStr==grade_B_date){
              $scope.gradeB.push(data[i])
            }
            else if(grade=="C" && dateStr==grade_C_date){
              $scope.gradeC.push(data[i])
            }
            else if(grade=="D" && dateStr==grade_D_date){
              $scope.gradeD.push(data[i])
            }
          }
          ////console.log($scope.busfill)
        }
        else{
          $scope.busfill = []
        }
      })
    }
    // $scope.getdata = function(){
    //   getBusfill.gettingbusfill().then(function(data){
    //     if(data){
    //       console.log(data)
    //       for(i=0;i<data.length;i++){
    //         var grade = data[i].grade
    //         if(grade=="A"){
    //           $scope.gradeA.push(data[i])
    //         }
    //         else if(grade=="B"){
    //           $scope.gradeB.push(data[i])
    //         }
    //         else if(grade=="C"){
    //           $scope.gradeC.push(data[i])
    //         }
    //         else if(grade=="D"){
    //           $scope.gradeD.push(data[i])
    //         }
    //       }
    //       //console.log($scope.busfill)
    //     }
    //     else{
    //       $scope.busfill = []
    //     }
    //   })
    // }

}]);

