//-----------------------------------------Vehicle Wise Battery Controller-------------------------------------------------
app.controller("VehicleWiseBatteryController",["postVehiclewisebattery","editVehiclewise","deleteVehiclewise","getBranch","getsociety","getvehiclereg","getVehiclewisebattery","getmodel","getvehiclesociety","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder","vehicle", function(postVehiclewisebattery,editVehiclewise,deleteVehiclewise,getBranch,getsociety,getvehiclereg,getVehiclewisebattery,getmodel,getvehiclesociety,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder,vehicle)  {
  $scope.Vehiclewisedata = [];
  $scope.societyname = [];
  $scope.branch = [];
  $scope.vehiclemake = [];
  $scope.vehiclereg = [];
  $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    $scope.search=function(val){
       vehicle.vehiclesearch(val).then(function(data){
         $scope.vehiclereg=data;
         // console.log($scope.Vehicle)
       })
    }
    $scope.click=function(reg){
        // console.log(reg)
      $scope.vehiclewisebattery.regno=reg
      getvehiclesociety.gettingvehiclesociety(reg).then(function(data){
        // console.log(data)
        $scope.vehiclewisebattery.society = data.society
        $scope.vehiclewisebattery.branch = data.branch
      })
      $scope.vehiclereg=[] 
    }

    $scope.saveVehiclewise = function(vehiclewisebattery) {
        //console.log(dailyvehicles)
        $scope.Vehiclewisedata.push(vehiclewisebattery);
        $scope.vehiclewisebattery = {};
        //console.log($scope.dailyvehicles);
        postVehiclewisebattery.postingVehiclewise(vehiclewisebattery)
    }
    $scope.editsaveVehiclewise = function(value){
      //console.log(value)
      editVehiclewise.editingVehiclewisedata(value)
    }
    $scope.removeVehiclewise = function(index,name){
      //console.log(name)
      deleteVehiclewise.deletingVehiclewisedata(name)
      $scope.Vehiclewisedata.splice(index, 1);
    }

    $scope.getdata=function(){
      getsociety.gettingsociety().then(function(data){
        if(data){
          $scope.societyname = data
          //console.log($scope.societyname)
        }
        else{
          $scope.societyname = []
        }
      })
      getBranch.gettingbranch().then(function(data){
        if(data){
          //console.log(data)
          $scope.branch = data
          //console.log($scope.branch)
        }
        else{
          $scope.branch = []
        }
      })
      getmodel.gettingModel().then(function(data){
        if(data){
          // console.log(data)
          $scope.vehiclemake = data
          //console.log($scope.vehiclemake)
        }
        else{
          $scope.vehiclemake = []
        }
      })
      
    }  
    $scope.getVehicleWiseData = function(){  
      getVehiclewisebattery.gettingVehiclewise().then(function(data){
        if(data){
          //console.log(data)
          $scope.Vehiclewisedata = data
          //console.log($scope.Dailyvehicle)
        }
        else{
          $scope.Vehiclewisedata = []
        }
      })
    }
}]);

