app.controller("BusBreakeDownController",["postBusBreake","editVehiclewise","deleteBusbreake","getBranch","getsociety","getvehiclereg","getBusbreakedata","getmodel","getvehiclesociety","$scope","DTOptionsBuilder", "DTColumnBuilder","DTColumnDefBuilder","vehicle", function(postBusBreake,editVehiclewise,deleteBusbreake,getBranch,getsociety,getvehiclereg,getBusbreakedata,getmodel,getvehiclesociety,$scope,DTOptionsBuilder, DTColumnBuilder,DTColumnDefBuilder,vehicle)  {
  $scope.breakedowndata = [];
  $scope.societyname = [];
  $scope.branch = [];
  $scope.vehiclemake = [];
  $scope.vehiclereg = [];

  $scope.busbreakedata = {workers:[{"worker":"","worker_designation":""},{"worker":'',"worker_designation":''},{"worker":'',"worker_designation":''},{"worker":'',"worker_designation":''},]};


  $scope.vm = {};
      $scope.vm.dtInstance = {};
      $scope.vm.dtColumnDefs = [DTColumnDefBuilder.newColumnDef(2).notSortable()];
      $scope.vm.dtOptions = DTOptionsBuilder.newOptions()
      .withOption('paging', true)
      .withOption('searching', true)
      .withOption('info', true)
      .withButtons([
      {
      extend:    'copy',
      text:      '<i class="fa fa-files-o"></i> Copy',
      titleAttr: 'Copy'
      },
      {
      extend:    'print',
      text:      '<i class="fa fa-print" aria-hidden="true"></i> Print',
      titleAttr: 'Print'
      },
      {
      extend:    'csvHtml5',
      text:      '<i class="fa fa-file-text-o"></i> csv',
      titleAttr: 'csv'
      },
      {
      extend:    'pdfHtml5',
      text:      '<i class="fa fa-file-pdf-o"></i> pdf',
      titleAttr: 'print'
      },
      {
      extend:    'excel',
      text:      '<i class="fa fa-file-excel-o"></i> Excel',
      titleAttr: 'Excel'
      },
      ]
      )
      ;
    $scope.search=function(val){
       vehicle.vehiclesearch(val).then(function(data){
         $scope.vehiclereg=data;
         // console.log($scope.Vehicle)
       })
    }
    $scope.click=function(reg){
        // console.log(reg)
      $scope.busbreakedata.regno=reg
      getvehiclesociety.gettingvehiclesociety(reg).then(function(data){
        // console.log(data)
        $scope.busbreakedata.society = data.society
        $scope.busbreakedata.branch = data.branch
      })
      $scope.vehiclereg=[] 
    }

    $scope.total = function(val){
      // console.log(val)
      // console.log(typeof val)
      // var testvalue = val
      // console.log(testvalue)
      $scope.busbreakedata.totalamount = val.travel_allowance + val.spare_part_amount + val.food_allowance 
      // console.log($scope.busbreakedata.totalamount)
    }

    $scope.addrow = function(){
      $scope.busbreakedata.workers.push({"worker":"","worker_designation":""})
    }

    $scope.removerow = function(){
      $scope.busbreakedata.workers.splice(0,1)
    }

    $scope.saveBusbreake = function(busbreake) {

        // console.log(busbreake)
        $scope.breakedowndata.push(busbreake);
        $scope.busbreakedata = {};
        //console.log($scope.dailyvehicles);
        postBusBreake.postingBusbreake(busbreake)
    }
    $scope.editsaveVehiclewise = function(value){
      //console.log(value)
      editVehiclewise.editingVehiclewisedata(value)
    }
    $scope.removeBusbreake = function(index,name){
      //console.log(name)
      deleteBusbreake.deletingBusbreakedata(name)
      $scope.breakedowndata.splice(index, 1);
    }

    $scope.printBusbreakedown = function(busbreake) {
      //console.log(transfers.society)
      var pdf = new jsPDF('p', 'pt','a4');
      pdf.setFontSize(10);
      var image='data:image/jpeg;base64,'
      pdf.addImage(image,'jpg',0,0,600,840);
      pdf.setFontSize(11);
      pdf.text(105,139,busbreake._id);
      pdf.text(500,139,busbreake.date);
      pdf.setFontSize(11);
      pdf.text(320,206,busbreake.busno);
      pdf.text(320,233,busbreake.drivername);
      pdf.text(320,263,busbreake.driverphoneno);
      pdf.text(320,293,busbreake.breakedownplace);
      pdf.text(320,323,busbreake.complaint);
      pdf.text(320,353,busbreake.message_received_time);
      pdf.text(320,380,busbreake.work_assign_time);
      pdf.text(320,410,busbreake.work_complete_time);
      // pdf.autoPrint();
      pdf.text(320,436,busbreake.status);
      pdf.text(320,465,busbreake.spare_part);
      pdf.text(320,603,busbreake.travel_allowance.toString());
      pdf.text(320,633,busbreake.spare_part_amount.toString());
      pdf.text(320,661,busbreake.food_allowance.toString());
      pdf.text(320,687,busbreake.totalamount.toString());
      for(i=0;i<busbreake.workers.length;i++){
        pdf.text(320,495 + i * 30, busbreake.workers[i].worker)
      }
      pdf.save(""+busbreake.busno+".pdf");
    }


    $scope.getdata=function(){
      getsociety.gettingsociety().then(function(data){
        if(data){
          $scope.societyname = data
          //console.log($scope.societyname)
        }
        else{
          $scope.societyname = []
        }
      })
      getBranch.gettingbranch().then(function(data){
        if(data){
          //console.log(data)
          $scope.branch = data
          //console.log($scope.branch)
        }
        else{
          $scope.branch = []
        }
      })
      getmodel.gettingModel().then(function(data){
        if(data){
          // console.log(data)
          $scope.vehiclemake = data
          //console.log($scope.vehiclemake)
        }
        else{
          $scope.vehiclemake = []
        }
      })
      
    }  
    $scope.getBusbreakingdata = function(){  
      getBusbreakedata.gettingbusbrakedaatas().then(function(data){
        if(data){
          //console.log(data)
          $scope.breakedowndata = data
          //console.log($scope.Dailyvehicle)
        }
        else{
          $scope.breakedowndata = []
        }
      })
    }
}]);

